  st_e            st;
  logic [BCW-1:0] wbeat;            // write beats sent so far
  logic           aw_done, w_done;  // AW handshaked / all W beats sent
  logic [AW-1:0]  aw_addr_q;        // latched write address
  logic [BCW-1:0] aw_len_q;         // latched write burst length (beats-1)

  // constant qualifiers
  assign axi_awid    = '0;
  assign axi_arid    = '0;
  assign axi_awburst = BURST_INCR;
  assign axi_arburst = BURST_INCR;
  assign axi_awsize  = AXSIZE;
  assign axi_arsize  = AXSIZE;
  assign axi_awcache = 4'b0011;     // normal non-cacheable bufferable
  assign axi_arcache = 4'b0011;
  assign axi_awprot  = 3'b000;
  assign axi_arprot  = 3'b000;

  // Write address/length are LATCHED at burst start: the W beats may all be
  // accepted before AWREADY, after which the GMM master is free to move on, so
  // AWADDR/AWLEN must not track live gmm_*. Read uses live gmm_* (single AR
  // command, master holds it until ARREADY).
  assign axi_awaddr  = aw_addr_q;
  assign axi_awlen   = {{(8-BCW){1'b0}}, aw_len_q};
  assign axi_araddr  = gmm_address;
  assign axi_arlen   = {{(8-BCW){1'b0}}, (gmm_burstcount - 1'b1)};
  assign axi_wdata   = gmm_writedata;
  assign axi_wstrb   = gmm_byteenable;
  assign axi_wlast   = (wbeat == aw_len_q);

  // channel valid/ready (AW and W presented together, each retired independently)
  assign axi_arvalid = (st == AX_RA);
  assign axi_rready  = (st == AX_RD);
  assign axi_awvalid = (st == AX_W) && !aw_done;
  assign axi_wvalid  = (st == AX_W) && !w_done;
  assign axi_bready  = (st == AX_WB);

  // GMM responses
  assign gmm_readdata      = axi_rdata;
  assign gmm_readdatavalid = (st == AX_RD) && axi_rvalid;

      state    <= S_IDLE;
      m_read   <= 1'b0;
      addr_q   <= '0;
      beat_cnt <= '0;
      valid    <= 1'b0;
    end else begin
      valid <= 1'b0;                    // default; pulsed in S_DATA completion

      if (clr) begin
        state  <= S_IDLE;
        m_read <= 1'b0;
      end else begin
        unique case (state)
          S_IDLE: begin
            if (start) begin
              // addr = base + index * DESC_BYTES
              addr_q   <= base_addr +
                          ({{(dma_pkg::HADDR_W-dma_pkg::LEN_W){1'b0}}, index} << $clog2(dma_pkg::DESC_BYTES));
              beat_cnt <= '0;
              m_read   <= 1'b1;
              state    <= S_CMD;
            end
          end

          S_CMD: begin
            // hold read until command accepted
            if (!m_waitrequest) begin
              m_read <= 1'b0;           // single burst command issued
              state  <= S_DATA;
            end
          end

          S_DATA: begin
            if (m_readdatavalid) begin
              beats[beat_cnt] <= m_readdata;
              if (beat_cnt == BCNT_W'(dma_pkg::DESC_BEATS-1)) begin
                state <= S_IDLE;
                valid <= 1'b1;          // all beats in -> decode is valid next cycle
              end else begin
                beat_cnt <= beat_cnt + 1'b1;
              end
            end
          end

          default: state <= S_IDLE;
        endcase
      end
    end
  end

  // assemble little-endian descriptor word and decode
  /* verilator lint_off UNUSEDSIGNAL */  // reserved bytes + unused-high sys_addr bits
  logic [dma_pkg::DESC_BITS-1:0] d;
  /* verilator lint_on UNUSEDSIGNAL */
  always_comb begin
    d = '0;
    for (int k = 0; k < dma_pkg::DESC_BEATS; k++)
      d[k*dma_pkg::DATA_W +: dma_pkg::DATA_W] = beats[k];
  end

  wire [31:0] ctrl_field = d[dma_pkg::DESC_CTRL_LSB +: 32];

  assign d_host_addr = d[dma_pkg::DESC_HOST_LSB +: dma_pkg::HADDR_W];
  assign d_sys_addr  = d[dma_pkg::DESC_SYS_LSB  +: dma_pkg::SADDR_W];
  assign d_length    = d[dma_pkg::DESC_LEN_LSB  +: dma_pkg::LEN_W];
  assign d_dir       = ctrl_field[dma_pkg::C_DIR];
  assign d_irq       = ctrl_field[dma_pkg::C_IRQ];
  assign d_last      = ctrl_field[dma_pkg::C_LAST];
  assign d_owned     = ctrl_field[dma_pkg::C_VALID];

endmodule

